// Balance reflex: after a push, command a step in the direction the pelvis is being pushed.
// Gains are m/s of command per m/s of pelvis velocity error; the dead band is in m/s.
import { Reflex } from './reflex.js';

const GAIN = 1.5;
const DEAD_BAND = 0.15;

export class KiroReflex extends Reflex {
  override command(s: { qpos: ArrayLike<number>; qvel: ArrayLike<number> }, base: ArrayLike<number>, out: Float64Array): void {
    const w = s.qpos[3] as number, x = s.qpos[4] as number, y = s.qpos[5] as number, z = s.qpos[6] as number;
    const yaw = Math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
    const c = Math.cos(yaw), sn = Math.sin(yaw);
    const wvx = s.qvel[0] as number, wvy = s.qvel[1] as number;
    // pelvis velocity in the heading frame, in m/s
    const vx = c * wvx + sn * wvy;
    const vy = -sn * wvx + c * wvy;
    const ex = vx - (base[0] as number), ey = vy - (base[1] as number);
    const sx = Math.abs(ex) > DEAD_BAND ? ex - Math.sign(ex) * DEAD_BAND : 0;
    const sy = Math.abs(ey) > DEAD_BAND ? ey - Math.sign(ey) * DEAD_BAND : 0;
    out[0] = (base[0] as number) + GAIN * sx;
    out[1] = (base[1] as number) + GAIN * sy;
    out[2] = base[2] as number;
  }
}

